    "love",
    "longing",
    "blessing"
  ],
  "cultural_notes": [
    {
      "expression": "Kebdti (كبدتي)",
      "literal": "my liver",
      "meaning": "An intense term of endearment for a child/grandchild, referring to them as one's own vital organ."
    },
    {
      "expression": "Lah yrdi 3lik (الله يرضي عليك)",
      "literal": "May God be pleased with you",
      "meaning": "A traditional parental blessing wishing divine favor, protection, and success upon a loved one."
    }
  ],
